export const faqs: Partial<Record<Route, Faq[]>> = {
  metso: [
    { q: ['Vállalnak Metso törőgép szervizt Magyarországon?', 'Do you service Metso crushers in Hungary?'], a: ['Igen. Helyszíni hibakeresést, megelőző karbantartást, valamint mechanikus, hidraulikus, villamos és vezérléstechnikai javítást is végzünk Metso törőberendezéseken.', 'Yes. We carry out on-site troubleshooting, preventive maintenance and mechanical, hydraulic, electrical and control-system repairs on Metso crushing equipment.'] },
    { q: ['Milyen Metso törőtípusokhoz tudnak segíteni?', 'Which Metso crusher types can you support?'], a: ['Pofás, kúpos, vízszintes tengelyű (HSI) és függőleges tengelyű (VSI) röpítőtörőkhöz, stacionárius és mobil kivitelben egyaránt. A Metso kínálatában a Nordberg® C Series™ pofás, valamint a GP és HP kúpos családok is megtalálhatók.', 'Jaw, cone, horizontal shaft impact (HSI) and vertical shaft impact (VSI) crushers, in both stationary and mobile configurations. Metso’s portfolio includes the Nordberg® C Series™ jaw crushers and the GP and HP cone families.'] },
    { q: ['Tudnak Metso kopóalkatrészt beszerezni?', 'Can you source Metso wear parts?'], a: ['Az alkatrészigényt a gép típustáblája, gyári száma és a keresett elem cikkszáma vagy fotója alapján azonosítjuk, majd erre adunk ajánlatot. Törőgépeken tipikusan törőpofák, kúpköpenyek, ütőlécek és rostafelületek kopnak a leggyorsabban.', 'We identify the parts requirement from the machine nameplate, serial number and the part number or a photo, then quote on that basis. On crushers the fastest-wearing items are typically jaw plates, mantles and concaves, blow bars and screening surfaces.'] },
    { q: ['Mobil és stacionárius Metso gépet is szervizelnek?', 'Do you service both mobile and stationary Metso machines?'], a: ['Igen. A Metso több törőcsaládot stacionárius, hordozható és mobil kivitelben is kínál, és mindhárom esetben a teljes rendszert vizsgáljuk: mechanika, hidraulika, villamosság és vezérléstechnika együtt.', 'Yes. Metso offers several crusher families in stationary, portable and mobile configurations, and in each case we assess the complete system: mechanics, hydraulics, electrics and controls together.'] },
    { q: ["Milyen gyorsan tudnak reagálni Metso üzemzavar esetén?", "How quickly can you respond to a Metso breakdown?"], a: ["A bejelentés után egyeztetjük a kiszállás időpontját. A határidőt a hiba jellege, a szükséges kopóalkatrészek elérhetősége és a szervizcsapat leterheltsége együtt határozza meg.", "We agree the site visit once the fault is reported. The lead time depends on the nature of the fault, the availability of the required wear parts and the service team’s workload."] },
    { q: ["Milyen adatokkal tudnak a leggyorsabban Metso ajánlatot adni?", "What data lets you quote fastest on a Metso machine?"], a: ["A törő típustáblája vagy gyári száma, a törési fokozat, az üzemóra, valamint a keresett alkatrész cikkszáma vagy fotója. Ezekkel az azonosítás általában egy körben lezárható.", "The crusher nameplate or serial number, the crushing stage, operating hours and the part number or a photo of the required item. With these, identification can usually be completed in one round."] },
  ],
  mj: [
    { q: ['Vállalnak M&J Recycling aprítógép szervizt?', 'Do you service M&J Recycling shredders?'], a: ['Igen. Négyfős, műszaki végzettségű szervizcsapatunk közvetlenül az M&J Recycling dániai szakembereinél szerzett gyártói képzést, és a megelőző karbantartástól a hibakeresésen át a mechanikus, hidraulikus, villamos és vezérléstechnikai javításig teljes körű szervizt nyújtunk.', 'Yes. Our four-person, technically qualified service team completed manufacturer training directly with M&J Recycling specialists in Denmark, and we provide comprehensive service from preventive maintenance and troubleshooting through to mechanical, hydraulic, electrical and control-system repairs.'] },
    { q: ['Mit jelent a vágóasztal és a kések hardfacing feltöltő hegesztése?', 'What does hardfacing of cutting tables and knives involve?'], a: ['A hardfacing feltöltő hegesztés során a kopott felületre kemény, kopásálló réteget hegesztünk fel, így az alkatrész geometriája helyreállítható teljes csere nélkül. Ez az M&J vágóasztalok és kések esetében kiemelt szakterületünk, többéves gyakorlati tapasztalattal.', 'Hardfacing rebuild welding deposits a hard, wear-resistant layer onto the worn surface, restoring the component geometry without full replacement. This is a core area of expertise for us on M&J cutting tables and knives, backed by several years of practical experience.'] },
    { q: ['Tudnak M&J előaprító és finomaprító alkatrészt szállítani?', 'Can you supply M&J pre-shredder and fine-shredder parts?'], a: ['Igen. A kések, vágóasztal-elemek, kopóbetétek és gépészeti alkatrészek igényét a gép típusa, gyári száma és a keresett elem alapján azonosítjuk, és ez alapján adunk ajánlatot.', 'Yes. We identify requirements for knives, cutting-table components, wear inserts and mechanical parts from the machine type, serial number and the specific item, and quote on that basis.'] },
    { q: ['Mi az M&J eDrive, és milyen előnye van?', 'What is M&J eDrive and what is the benefit?'], a: ['Az eDrive előaprítók a hagyományos hidraulikus hajtás helyett elektromos hajtásláncot használnak. A gyártó P4000e oldala akár 80% energia-megtakarítást ad meg a hidraulikus aprítókhoz képest, a ReCapture rendszerre pedig további, akár 25%-os megtakarítást jelöl meg. Ezek gyártói adatok.', 'eDrive pre-shredders use an electric drivetrain instead of conventional hydraulic drive. The manufacturer’s P4000e page states up to 80% energy savings compared with hydraulic shredders, and a further saving of up to 25% for the ReCapture system. These are manufacturer figures.'] },
    { q: ['Milyen hulladékáramokhoz használhatók az M&J aprítók?', 'Which waste streams are M&J shredders used for?'], a: ['Kommunális, ipari, fa-, építési és egyéb hulladékáramok elő- és finomaprításához, többek között RDF/SRF előállításához. A megfelelő folyamat kialakításánál az anyagösszetétel, az elvárt frakció és a további válogatási vagy hasznosítási lépés is lényeges.', 'Pre-shredding and fine-shredding of municipal, industrial, wood, construction and other waste streams, including RDF/SRF production. Material composition, the required fraction and downstream sorting or recovery steps all matter when configuring the process.'] },
    { q: ["Milyen adatok kellenek egy M&J megkereséshez?", "What data is needed for an M&J enquiry?"], a: ["Az aprító típusa és gyári száma, a feldolgozott hulladékáram, valamint a kopott kés vagy vágóasztal fotója. A hardfacing igény felméréséhez a kopott felület képei a leghasznosabbak.", "The shredder type and serial number, the waste stream processed, and photos of the worn knife or cutting table. For assessing a hardfacing requirement, images of the worn surface are the most useful."] },
  ],
  mfl: [
    { q: ['Tudnak régi MFL törőgéphez alkatrészt biztosítani?', 'Can you provide parts for older MFL crushers?'], a: ['Igen, de minden esetben azonosítással kezdünk. A rendelkezésre álló dokumentáció, az alkatrész mintadarabja vagy fotója, a felmért méretek és a beépítési környezet alapján határozzuk meg biztonsággal a következő lépést.', 'Yes, though we always start with identification. The available documentation, a sample or photo of the part, measured dimensions and the installation environment let us determine the right next step with confidence.'] },
    { q: ['Mi a helyzet, ha nincs meg a gép dokumentációja?', 'What if the machine documentation is missing?'], a: ['Ez a régi gépparknál gyakori. Ilyenkor a típustáblából, a helyszíni felmérésből, a kopott alkatrész mintadarabjából és a beépítési helyről készült fotókból indulunk ki, és ezekből építjük fel a szükséges műszaki adatokat.', 'This is common with older fleets. In that case we work from the nameplate, an on-site survey, a sample of the worn part and photos of the installation point, and build up the required technical data from those.'] },
    { q: ['Az MFL és az SBM ugyanaz a termékkör?', 'Are MFL and SBM the same product range?'], a: ['Nem. Ezen az oldalon kifejezetten a régi Maschinenfabrik Liezen – MFL – berendezésekről van szó, nem az SBM mai termékportfóliójáról. A Maschinenfabrik Liezen und Gießerei osztrák gépgyártó és öntödei vállalat, amely Liezenben működik.', 'No. This page specifically concerns older Maschinenfabrik Liezen — MFL — equipment, not the current SBM product portfolio. Maschinenfabrik Liezen und Gießerei is an Austrian engineering and foundry company based in Liezen.'] },
    { q: ['Érdemes a régi MFL gépet javítani, vagy inkább cserélni?', 'Is it worth repairing an older MFL machine or replacing it?'], a: ['Ha a mechanika még jó állapotban van, a javítás és a vezérléskorszerűsítés gyakran gazdaságosabb a gépcserénél. Az állapotfelmérés után reális képet adunk arról, mi javítható és mi az, aminél a csere indokolt.', 'If the mechanics are still sound, repair and control-system modernisation are often more economical than replacement. After a condition assessment we give a realistic picture of what can be repaired and where replacement is justified.'] },
    { q: ['Vállalnak MFL gépen vezérléskorszerűsítést?', 'Do you carry out control-system modernisation on MFL machines?'], a: ['Igen. Régi mobil és stacionárius berendezéseknél részleges vagy teljes retrofitot is vállalunk: PLC, kezelői kijelző, I/O rendszer, szenzorika, kábelezés és CAN-alapú kommunikáció korszerűsítését.', 'Yes. For older mobile and stationary equipment we carry out partial or complete retrofits: PLC, operator display, I/O system, sensors, wiring and CAN-based communication.'] },
    { q: ["Milyen adatokból tudnak elindulni egy régi MFL gépnél?", "What data lets you start work on an older MFL machine?"], a: ["A típustábla fotója és a gyári szám a kiindulópont. Ha ezek már nem olvashatók, a helyszíni felmérés, a kopott alkatrész mintadarabja és a beépítési helyről készült képek alapján dolgozunk.", "A photo of the nameplate and the serial number are the starting point. Where these are no longer legible we work from an on-site survey, a sample of the worn part and images of the installation point."] },
  ],
  outotec: [
    { q: ['Milyen Outotec berendezésekhez nyújtanak támogatást?', 'Which Outotec equipment do you support?'], a: ['Az Outotec névhez kötődő technológiák tipikusan ásványfeldolgozási és anyagkezelési feladatokban jelennek meg. A támogatás megkezdése előtt a berendezés konkrét termékcsoportját, gyári azonosítóját és az üzemi feladatot tisztázzuk.', 'Technologies associated with the Outotec name are typically used in mineral-processing and material-handling duties. Before starting, we establish the specific product group, factory identification and operating duty.'] },
    { q: ['Az Outotec ma a Metso része?', 'Is Outotec now part of Metso?'], a: ['A márkanév vállalati háttere megváltozott: a Metso és az Outotec 2020-ban Metso Outotec néven egyesült, a vállalat pedig 2023-ban visszatért a Metso névhez. Nálunk az Outotec megnevezés a Geinvest képviseletéhez tartozó termékkört jelöli.', 'The corporate background changed: Metso and Outotec merged as Metso Outotec in 2020, and the company returned to the Metso name in 2023. On our site, Outotec denotes the product range represented by Geinvest.'] },
    { q: ['Tudnak Outotec alkatrészt beszerezni?', 'Can you source Outotec parts?'], a: ['Igen. Az alkatrész- és kopóalkatrész-igényt a berendezés azonosítása után, a gyári adatok és a keresett elem cikkszáma vagy fotója alapján mérjük fel, majd ez alapján adunk ajánlatot.', 'Yes. Once the equipment is identified, we assess parts and wear-parts requirements from the factory data and the part number or a photo, then quote on that basis.'] },
    { q: ['Vállalnak helyszíni Outotec szervizt Magyarországon?', 'Do you provide on-site Outotec service in Hungary?'], a: ['Igen. A Geinvest az Outotec termékekhez karbantartást, hibakeresést és javítást is biztosít, a mechanikus és hidraulikus munkáktól a villamos és vezérléstechnikai feladatokig.', 'Yes. Geinvest provides maintenance, troubleshooting and repair for Outotec products, from mechanical and hydraulic work through to electrical and control-system tasks.'] },
    { q: ["Mennyi idő alatt tudnak Outotec berendezéshez kiszállni?", "How soon can you attend an Outotec machine?"], a: ["A kiszállást a berendezés azonosítása után tudjuk ütemezni, mert ez határozza meg a szükséges szakembert és alkatrészeket. A konkrét időpontot minden esetben visszaigazoljuk.", "We can schedule the visit once the equipment is identified, as this determines the specialists and parts required. We always confirm a specific date."] },
    { q: ["Milyen adatokat kérnek egy Outotec megkeresés indításához?", "What data do you need to open an Outotec enquiry?"], a: ["A berendezés termékcsoportja és gyári azonosítója, az üzemi feladat, valamint a keresett alkatrész cikkszáma vagy fotója. Ezek nélkül a termékkör nem határozható meg biztonsággal.", "The product group and factory identification of the equipment, the operating duty, and the part number or a photo of the required item. Without these the product range cannot be established reliably."] },
  ],
  metsoService: [
    { q: ['Kiszállnak helyszíni Metso javításra?', 'Do you travel to site for Metso repairs?'], a: ['Igen, a szerviz nagy része helyszínen zajlik. A kiszállás előtt a gép adatai és a hibaleírás alapján összeállítjuk a szükséges szerszámokat és a valószínűsíthető alkatrészeket.', 'Yes, most of our service work is carried out on site. Before travelling we assemble the necessary tools and the parts likely to be needed, based on the machine data and fault description.'] },
    { q: ['Végeznek megelőző karbantartást is, nem csak hibajavítást?', 'Do you also carry out preventive maintenance, not just repairs?'], a: ['Igen. Az állapotfelmérés során azonosítjuk a várható hibákat és a kopóalkatrészeket, így a leállás tervezhetővé válik a váratlan üzemzavar helyett.', 'Yes. During condition assessment we identify likely faults and wear parts, which makes downtime plannable instead of unexpected.'] },
    { q: ['Tudnak PLC- és CAN-hibát is keresni a törőn?', 'Can you also diagnose PLC and CAN faults on the crusher?'], a: ['Igen. PLC-vezérlés, I/O, valamint CAN, CANopen és J1939 kommunikáció diagnosztikáját és szoftveres hibakeresését is vállaljuk, nem csak a gépészeti részt.', 'Yes. We cover PLC controls, I/O and CAN, CANopen and J1939 communication diagnostics and software troubleshooting, not only the mechanical side.'] },
    { q: ["Mennyi idő alatt tudnak kiszállni törőgép leállás esetén?", "How soon can you attend a crusher stoppage?"], a: ["A kiszállás időpontját a bejelentés után egyeztetjük. Mivel a szükséges alkatrészeket előre összeállítjuk, a pontos határidő a hiba jellegétől és az alkatrészek elérhetőségétől függ.", "We agree the visit once the stoppage is reported. Because we assemble the required parts in advance, the exact lead time depends on the nature of the fault and part availability."] },
  ],
  metsoParts: [
    { q: ['Honnan tudják, melyik alkatrész illik a gépembe?', 'How do you determine which part fits my machine?'], a: ['A gép típustáblája és gyári száma, valamint a keresett elem cikkszáma vagy fotója alapján. Ugyanaz a gépcsalád több kivitelben is előfordul, ezért ezek nélkül nagy a hibás rendelés kockázata.', 'From the machine nameplate and serial number together with the part number or a photo. The same crusher family exists in several configurations, so without these the risk of ordering the wrong item is high.'] },
    { q: ['Csak kopóalkatrészt tudnak szállítani?', 'Do you only supply wear parts?'], a: ['Nem. A kopóelemeken túl gépészeti alkatrészeket, csapágyakat, tömítéseket és hajtáselemeket, valamint hidraulikus és villamos elemeket is beszerzünk.', 'No. Beyond wear items we also source mechanical components, bearings, seals and drive elements, as well as hydraulic and electrical parts.'] },
    { q: ['Érdemes lehet a kopott alkatrészt felújítani?', 'Might it be worth refurbishing a worn part?'], a: ['Bizonyos kopófelületek feltöltő hegesztéssel helyreállíthatók, ami gyorsabb és költséghatékonyabb lehet a teljes cserénél. Az állapot ismeretében adunk erre javaslatot.', 'Some wear surfaces can be restored by rebuild welding, which may be faster and more economical than full replacement. We advise on this once the condition is known.'] },
    { q: ["Mennyi idő egy Metso alkatrész beazonosítása?", "How long does identifying a Metso part take?"], a: ["Ha a típustábla, a gyári szám és a keresett elem fotója rendelkezésre áll, az azonosítás jellemzően rövid. Hiányos adatok esetén helyszíni felmérés vagy méretfelvétel is szükséges lehet.", "With the nameplate, serial number and a photo of the item available, identification is typically quick. Where data is incomplete, an on-site survey or dimensional check may also be needed."] },
  ],
  mjService: [
    { q: ['Mennyi ideig tart egy vágóasztal hardfacing felújítása?', 'How long does a cutting-table hardfacing rebuild take?'], a: ['A ráfordítás a kopás mértékétől és a felület méretétől függ, ezért a felmérés után adunk konkrét időbecslést. A tervezhetőség érdekében a felújítást általában karbantartási leálláshoz igazítjuk.', 'The effort depends on the extent of wear and the size of the surface, so we give a specific estimate after assessment. To keep it plannable we usually align the rebuild with a maintenance shutdown.'] },
    { q: ['Az eDrive gépek villamos hajtásláncához is értenek?', 'Are you familiar with the electric drivetrain on eDrive machines?'], a: ['Igen. A villamos és vezérléstechnikai javítás a szolgáltatásunk része, így az elektromos hajtású gépeknél sem külön szolgáltatóhoz kell fordulni.', 'Yes. Electrical and control-system repair is part of our service, so electric-drive machines do not require a separate provider.'] },
    { q: ['Vállalnak rendszeres karbantartási ütemezést?', 'Do you take on a regular maintenance schedule?'], a: ['A megelőző karbantartás ütemezését az üzemórák és a feldolgozott anyag alapján egyeztetjük. A konkrét feltételeket minden esetben egyedileg beszéljük meg.', 'We agree the preventive maintenance schedule based on operating hours and the processed material. Specific terms are always discussed individually.'] },
    { q: ["Mennyi idő alatt tudnak reagálni aprítógép leállásra?", "How soon can you respond to a shredder stoppage?"], a: ["A bejelentés után egyeztetjük a kiszállást. Mivel a hulladékfeldolgozásban a leállás gyorsan feltorlódást okoz, a hibaleírás és néhány fotó alapján előre felkészülünk a valószínű javításra.", "We agree the visit once the stoppage is reported. As downtime in waste processing quickly causes a backlog, we prepare for the likely repair in advance from the fault description and a few photos."] },
  ],
  mjParts: [
    { q: ['Milyen adat kell egy M&J késrendeléshez?', 'What data is needed to order M&J knives?'], a: ['A gép típusa és gyári száma, a kés pozíciója, valamint a meglévő kés cikkszáma vagy méretezett fotója. Ezek alapján azonosítjuk a megfelelő kivitelt.', 'The machine type and serial number, the knife position and the part number or a dimensioned photo of the existing knife. These let us identify the correct version.'] },
    { q: ['Új kés vagy felújítás gazdaságosabb?', 'Is a new knife or a rebuild more economical?'], a: ['Ez a kopás mértékétől függ. A felmérés után megmondjuk, hogy a hardfacing feltöltő hegesztés vagy az új alkatrész beépítése a jobb megoldás az adott elemnél.', 'It depends on the extent of wear. After assessment we advise whether hardfacing rebuild welding or a new part is the better option for that item.'] },
    { q: ['Szállítanak hegesztőanyagot is a helyreállításhoz?', 'Do you also supply welding consumables for restoration?'], a: ['A hardfacing munkát általában mi végezzük, de a kopásálló hegesztőanyagok igényét is fel tudjuk mérni, ha a helyreállítás saját műhelyben történik.', 'We usually carry out the hardfacing work ourselves, but we can also assess wear-resistant welding consumable requirements if the restoration is done in your own workshop.'] },
    { q: ["Tudnak teljes késkészletet egyszerre szállítani?", "Can you supply a complete set of knives at once?"], a: ["Igen, az igényt a gép típusa és a késpozíciók alapján mérjük fel. Teljes készlet cseréjénél a vágóasztal állapotát is érdemes egyszerre megvizsgálni.", "Yes, we assess the requirement from the machine type and knife positions. When replacing a full set it is worth inspecting the cutting table condition at the same time."] },
  ],
  mflService: [
    { q: ['Megnézik a gépet a helyszínen, mielőtt ajánlatot adnak?', 'Do you inspect the machine on site before quoting?'], a: ['Régi MFL berendezésnél ez a legbiztosabb út. A helyszíni felmérés során dokumentáljuk a meglévő kivitelt, és ezután adunk reális javítási vagy felújítási javaslatot.', 'With older MFL equipment this is the most reliable route. During the site survey we document the existing configuration and then give a realistic repair or refurbishment proposal.'] },
    { q: ['Csak a vezérlést lehet korszerűsíteni, vagy a gépészetet is?', 'Can only the controls be modernised, or the mechanics too?'], a: ['Mindkettő szóba jön. A retrofit lehet részleges, csak a vezérlésre kiterjedő, de a kopott gépészeti részegységek javítását is elvégezzük ugyanazon a gépen.', 'Both are possible. A retrofit can be partial and cover only the controls, but we also repair worn mechanical assemblies on the same machine.'] },
    { q: ['Mennyire kockázatos egy régi gépet felújítani?', 'How risky is refurbishing an older machine?'], a: ['A kockázatot az állapotfelmérés csökkenti. Ha egy részegység már nem javítható gazdaságosan, ezt előre jelezzük, nem a munka közben derül ki.', 'Condition assessment reduces the risk. If an assembly can no longer be repaired economically we flag it in advance, rather than it emerging mid-project.'] },
    { q: ["Mit érdemes előkészíteni a helyszíni felmérés előtt?", "What should be prepared before the site survey?"], a: ["Minden megmaradt dokumentációt, rajzot és korábbi javítási feljegyzést, valamint a gép hozzáférhetőségét. Ezek alapján a felmérés egy alkalommal is lezárható.", "Any surviving documentation, drawings and previous repair records, plus access to the machine. With these the survey can often be completed in a single visit."] },
  ],
  mflParts: [
    { q: ['Van esély alkatrészre, ha a gép több évtizedes?', 'Is there any chance of parts for a machine that is decades old?'], a: ['Sok esetben igen, de ez az azonosítás eredményétől függ. Előfordul, hogy katalógusból elérhető alkatrész helyett a méret alapján legyártatható vagy felújítható elem a járható út.', 'Often yes, though it depends on the outcome of identification. Sometimes an item made to measure or a refurbished part is the viable route rather than a catalogue part.'] },
    { q: ['Elég egy fotó az alkatrészről?', 'Is a photo of the part enough?'], a: ['A fotó jó kiindulás, de a biztos azonosításhoz általában méretek is szükségesek. A legjobb, ha a kopott alkatrész mintadarabja is rendelkezésre áll.', 'A photo is a good starting point, but reliable identification usually needs dimensions as well. Best of all is having the worn part available as a sample.'] },
    { q: ['Mit tesznek, ha az eredeti alkatrész már nem elérhető?', 'What happens if the original part is no longer available?'], a: ['Ilyenkor felmérjük, hogy az elem javítható, felújítható vagy méret alapján pótolható. A döntés előtt mindig tisztázzuk, milyen műszaki feltételeknek kell megfelelnie.', 'In that case we assess whether the item can be repaired, refurbished or replaced to measure. Before deciding we always clarify the technical requirements it must meet.'] },
    { q: ["Mennyi idő egy MFL alkatrész beszerzése?", "How long does sourcing an MFL part take?"], a: ["Ez az azonosítás eredményétől függ. Ha az elem méret alapján legyártatható vagy felújítható, a határidőt a gyártási vagy javítási kapacitás határozza meg, amit előre visszaigazolunk.", "This depends on the outcome of identification. If the item can be made to measure or refurbished, the lead time is set by manufacturing or repair capacity, which we confirm in advance."] },
  ],
  outotecService: [
    { q: ['Mivel kezdődik egy Outotec szervizmegkeresés?', 'How does an Outotec service enquiry begin?'], a: ['A berendezés konkrét termékcsoportjának, gyári azonosítójának és üzemi feladatának tisztázásával. Ezután tudjuk megmondani, milyen karbantartás vagy javítás indokolt.', 'By establishing the specific product group, factory identification and operating duty of the equipment. Only then can we advise which maintenance or repair is appropriate.'] },
    { q: ['A villamos és vezérlési hibákat is vállalják?', 'Do you also handle electrical and control faults?'], a: ['Igen. A mechanikus és hidraulikus munkán túl villamos javítást, valamint PLC- és CAN-diagnosztikát is végzünk.', 'Yes. Beyond mechanical and hydraulic work we also carry out electrical repair and PLC and CAN diagnostics.'] },
    { q: ['Miért szerepel még az Outotec név, ha a vállalat ma Metso?', 'Why is the Outotec name still used if the company is now Metso?'], a: ['A Metso és az Outotec 2020-ban Metso Outotec néven egyesült, majd a vállalat 2023-ban visszatért a Metso névhez. Nálunk az Outotec megnevezés a Geinvest képviseletéhez tartozó termékkört jelöli.', 'Metso and Outotec merged as Metso Outotec in 2020, and the company returned to the Metso name in 2023. On our site, Outotec denotes the product range represented by Geinvest.'] },
    { q: ["Milyen határidővel tudnak Outotec javítást vállalni?", "What lead time applies to an Outotec repair?"], a: ["A határidőt a berendezés azonosítása, a hiba jellege és az alkatrészek elérhetősége együtt adja. Ezért a felmérés után adunk konkrét, visszaigazolt időpontot.", "The lead time depends on equipment identification, the nature of the fault and part availability. We therefore give a specific, confirmed date after assessment."] },
  ],
  outotecParts: [
    { q: ['Milyen adat kell egy Outotec alkatrész-ajánlathoz?', 'What data is needed for an Outotec parts quotation?'], a: ['A berendezés gyári azonosítója és termékcsoportja, a keresett elem cikkszáma vagy fotója, valamint néhány kép a beépítési helyről.', 'The factory identification and product group of the equipment, the part number or a photo of the required item, and a few images of the installation point.'] },
    { q: ['Tudnak kopóalkatrészt is szállítani?', 'Can you supply wear parts as well?'], a: ['Igen, a kopóalkatrészek és a gépészeti alkatrészek igényét egyaránt felmérjük, majd a beazonosított elemekre adunk ajánlatot.', 'Yes, we assess both wear-part and mechanical component requirements, then quote on the identified items.'] },
    { q: ['Az alkatrészcsere mellett a hiba okát is megvizsgálják?', 'Alongside replacing the part, do you investigate the cause?'], a: ['Igen. Ha a kopás oka gépészeti vagy vezérlési probléma, az alkatrész cseréje önmagában nem tartós megoldás, ezért ezeket együtt vizsgáljuk.', 'Yes. If the wear is caused by a mechanical or control problem, replacing the part alone is not a lasting solution, so we examine them together.'] },
    { q: ["Mennyi idő az Outotec alkatrészek beszerzése?", "How long does sourcing Outotec parts take?"], a: ["A beazonosítás után tudjuk megadni. A kopóalkatrészek és a gépészeti elemek elérhetősége eltérő lehet, ezért a határidőt elemenként igazoljuk vissza.", "We can state this once identification is complete. Availability can differ between wear parts and mechanical components, so we confirm lead times item by item."] },
  ],
}
export const brandOf: Partial<Record<Route, string>> = { metso: 'Metso', mj: 'M&J Recycling', mfl: 'MFL', outotec: 'Outotec', metsoService: 'Metso', metsoParts: 'Metso', mjService: 'M&J Recycling', mjParts: 'M&J Recycling', mflService: 'MFL', mflParts: 'MFL', outotecService: 'Outotec', outotecParts: 'Outotec' }
export const parentOf: Partial<Record<Route, Route>> = { metsoService: 'metso', metsoParts: 'metso', mjService: 'mj', mjParts: 'mj', mflService: 'mfl', mflParts: 'mfl', outotecService: 'outotec', outotecParts: 'outotec' }
export const brandHubRoutes: Route[] = ['metso', 'mj', 'mfl', 'outotec']
export const partsRoutes: Route[] = ['metsoParts', 'mjParts', 'mflParts', 'outotecParts']
export const serviceRoutes: Route[] = ['metsoService', 'mjService', 'mflService', 'outotecService']
export function serviceTypeOf(route: Route, brand: string): Pair {
  if (partsRoutes.includes(route)) return [`${brand} alkatrész- és kopóalkatrész-ellátás`, `${brand} parts and wear-parts supply`]
  if (serviceRoutes.includes(route)) return [`${brand} berendezések javítása és karbantartása`, `${brand} equipment repair and maintenance`]
  return [`${brand} berendezések műszaki támogatása, javítása és alkatrészellátása`, `${brand} equipment technical support, repair and parts supply`]
}

