export const siblingOf: Partial<Record<Route, Route>> = { metsoService: 'metsoParts', metsoParts: 'metsoService', mjService: 'mjParts', mjParts: 'mjService', mflService: 'mflParts', mflParts: 'mflService', outotecService: 'outotecParts', outotecParts: 'outotecService' }
export const intentsOf: Partial<Record<Route, [Route, Route]>> = { metso: ['metsoService', 'metsoParts'], mj: ['mjService', 'mjParts'], mfl: ['mflService', 'mflParts'], outotec: ['outotecService', 'outotecParts'] }
export function intentLinksFor(route: Route): [Route, Pair][] {
  const pair = intentsOf[route]
  const links: [Route, Pair][] = pair ? pair.map((item) => [item, relatedLabel(item)] as [Route, Pair]) : []
  links.push(['service', ['Szerviz és retrofit szolgáltatások', 'Service and retrofit capabilities']], ['contact', ['Kapcsolat és ajánlatkérés', 'Contact and enquiries']])
  return links
}
export function relatedLabel(route: Route): Pair {
  const brand = brandOf[route] ?? ''
  if (partsRoutes.includes(route)) return [`${brand} alkatrész és kopóalkatrész`, `${brand} parts and wear parts`]
  if (serviceRoutes.includes(route)) return [`${brand} javítás és karbantartás`, `${brand} repair and maintenance`]
  return [`${brand} áttekintés`, `${brand} overview`]
}

