/** Schema.org @graph for a page. Shared by the runtime head updater and the build-time HTML injector. */
export function structuredData(route: Route, locale: Locale): Record<string, unknown> {
  const [name, description] = meta[locale][route]
  const pageUrl = `${origin}${paths[locale][route]}`
  const inLanguage = locale === 'hu' ? 'hu-HU' : 'en'
  const brand = brandOf[route]
  const parent = parentOf[route]
  const crumbs: Record<string, unknown>[] = [{ '@type': 'ListItem', position: 1, name: locale === 'hu' ? 'Főoldal' : 'Home', item: `${origin}${paths[locale].home}` }]
  if (parent && brand) crumbs.push({ '@type': 'ListItem', position: 2, name: brand, item: `${origin}${paths[locale][parent]}` })
  crumbs.push({ '@type': 'ListItem', position: crumbs.length + 1, name, item: pageUrl })
  const graph: Record<string, unknown>[] = [
    { '@type': ['Organization', 'LocalBusiness'], '@id': `${origin}/#organization`, name: 'Geinvest Kft.', url: origin, logo: `${origin}/favicon.png`, telephone: phone, email, address: { '@type': 'PostalAddress', streetAddress: 'Petőfi utca 1/C.', postalCode: '2181', addressLocality: 'Iklad', addressCountry: 'HU' }, areaServed: { '@type': 'Country', name: 'Hungary' } },
    { '@type': 'WebSite', '@id': `${origin}/#website`, url: origin, name: 'Geinvest Kft.', publisher: { '@id': `${origin}/#organization` }, inLanguage: ['hu-HU', 'en'] },
    { '@type': 'WebPage', '@id': `${pageUrl}#webpage`, url: pageUrl, name, description, inLanguage, isPartOf: { '@id': `${origin}/#website` }, breadcrumb: { '@id': `${pageUrl}#breadcrumb` } },
    { '@type': 'BreadcrumbList', '@id': `${pageUrl}#breadcrumb`, itemListElement: crumbs },
  ]
  if (brand) graph.push({ '@type': 'Service', '@id': `${pageUrl}#service`, name, description, url: pageUrl, provider: { '@id': `${origin}/#organization` }, areaServed: { '@type': 'Country', name: 'Hungary' }, serviceType: tx(locale, ...serviceTypeOf(route, brand)) })
  const items = faqs[route]
  if (items?.length) graph.push({ '@type': 'FAQPage', '@id': `${pageUrl}#faq`, inLanguage, mainEntity: items.map((item) => ({ '@type': 'Question', name: tx(locale, ...item.q), acceptedAnswer: { '@type': 'Answer', text: tx(locale, ...item.a) } })) })
  return { '@context': 'https://schema.org', '@graph': graph }
}

const escapes: Record<string, string> = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }
function esc(value: string) { return value.replace(/[&<>"]/g, (character) => escapes[character]) }

/** Head tags for a page. `depth` is how many directories deep the HTML file sits, for the relative favicon. */
export function headTags(route: Route, locale: Locale, depth: number): string {
  const [title, description] = meta[locale][route]
  const canonical = `${origin}${paths[locale][route]}`
  const favicon = `${'../'.repeat(depth) || './'}favicon.png`
  return [
    `<title>${esc(title)}</title>`,
    `<meta name="description" content="${esc(description)}" />`,
    `<link rel="canonical" href="${canonical}" />`,
    `<link rel="alternate" hreflang="hu" href="${origin}${paths.hu[route]}" />`,
    `<link rel="alternate" hreflang="en" href="${origin}${paths.en[route]}" />`,
    `<link rel="alternate" hreflang="x-default" href="${origin}${paths.hu[route]}" />`,
    `<meta property="og:title" content="${esc(title)}" />`,
    `<meta property="og:description" content="${esc(description)}" />`,
    `<meta property="og:type" content="website" />`,
    `<meta property="og:url" content="${canonical}" />`,
    `<meta property="og:image" content="${ogImage}" />`,
    `<meta property="og:locale" content="${locale === 'en' ? 'en_US' : 'hu_HU'}" />`,
    `<meta name="twitter:card" content="summary_large_image" />`,
    `<link rel="icon" type="image/png" href="${favicon}" />`,
    `<script type="application/ld+json">${JSON.stringify(structuredData(route, locale)).replace(/</g, '\\u003c')}</script>`,
  ].join('\n    ')
}

/**
 * Crawlable page content placed inside #root. React clears the container on mount, so this is a
 * no-JS fallback and a complete copy of the page's key text for crawlers that do not execute JS.
 */
export function staticBody(route: Route, locale: Locale): string {
  const t = (pair: Pair) => esc(tx(locale, ...pair))
  const head = pageHeads[route]
  const intent = intents[route]
  const guide = hubGuides[route]
  const items = faqs[route]
  const parts: string[] = [`<div class="page-head"><div class="container"><p class="kicker">${t(head.kicker)}</p><h1>${t(head.title).replace('|', '<br />')}</h1><p>${t(head.lead)}</p></div></div>`]
  const body: string[] = []
  if (intent) {
    body.push(`<h2>${t(intent.listTitle)}</h2><ul>${intent.bullets.map((bullet) => `<li>${t(bullet)}</li>`).join('')}</ul>`)
    body.push(intent.body.map((block) => `<h2>${t(block.h)}</h2><p>${t(block.p)}</p>`).join(''))
    if (intent.note) body.push(`<p>${t(intent.note)}</p>`)
  }
  if (guide) {
    body.push(`<h2>${tx(locale, 'Szerviz, alkatrész és műszaki támogatás', 'Service, parts and technical support')}</h2><p>${t(guide.applications)}</p>`)
    body.push(`<h2>${tx(locale, 'Miben tudunk segíteni?', 'How we can help')}</h2><ul>${guide.services.map((service) => `<li>${t(service)}</li>`).join('')}</ul>`)
  }
  if (!intent && !guide) body.push(`<p>${esc(meta[locale][route][1])}</p>`)
  if (items?.length) body.push(`<h2>${tx(locale, 'Gyakori kérdések', 'Frequently asked questions')}</h2>${items.map((item) => `<h3>${t(item.q)}</h3><p>${t(item.a)}</p>`).join('')}`)
  const links = [...new Set([...navRoutes, ...(intentsOf[route] ?? []), ...(parentOf[route] ? [parentOf[route]!] : []), ...(siblingOf[route] ? [siblingOf[route]!] : []), ...brandHubRoutes])].filter((item) => item !== route)
  body.push(`<h2>${tx(locale, 'Oldalak', 'Pages')}</h2><ul>${links.map((item) => `<li><a href="${paths[locale][item]}">${esc(meta[locale][item][0].split(' | ')[0])}</a></li>`).join('')}</ul>`)
  parts.push(`<div class="section"><div class="container prose">${body.join('')}</div></div>`)
  return parts.join('\n      ')
}
